from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # employee -> year -> number of days used
        self._used: dict[str, dict[int, int]] = {}

    def _count_leave_days(self, start: date, end: date) -> list[date]:
        days = []
        cur = start
        while cur <= end:
            if cur.weekday() < 5 and cur not in self.holidays:
                days.append(cur)
            cur += timedelta(days=1)
        return days

    def _used_for(self, employee: str, year: int) -> int:
        return self._used.get(employee, {}).get(year, 0)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date")
        if (start - today).days < 3:
            raise ValueError("Leave must be requested at least 3 days in advance")

        days = self._count_leave_days(start, end)
        count = len(days)

        # Group by year (a request may span a year boundary).
        by_year: dict[int, int] = {}
        for d in days:
            by_year[d.year] = by_year.get(d.year, 0) + 1

        # Validate against per-year allowance before committing anything.
        for year, n in by_year.items():
            if self._used_for(employee, year) + n > self.days_per_year:
                raise ValueError("Not enough leave days remaining")

        emp_usage = self._used.setdefault(employee, {})
        for year, n in by_year.items():
            emp_usage[year] = emp_usage.get(year, 0) + n

        return count

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used_for(employee, year)
